head.script:
scwin.gVar = {
    "cMinByteLength" : "",
    "cValue" : "",
    "cSubProperty" : "",
    "cDisplaymessage" : "",
    "cInvalidMessage" : "",
    "cInvalidMessageFunc" : "",
}



// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[secret > P > minByteLength]<br/>Secret 컴포넌트에 입력하는 값의 최소 Byte 수를 설정합니다.",
    "validation" : [
        "입력값 유효성 체크 시 사용되는 속성으로 validate() 메소드로 유효성 체크를 수행합니다.",
        "문자를 Byte 로 계산하여 입력값의 최소 Byte 를 숫자로 설정합니다.",
        "config.xml 의 WebSquare/byteCheckEncoding/@value 값을 기준으로 'euc-kr' 은 2Byte, 'utf-8' 은 3Byte 로 다국어 문자를 계산합니다.",
        "값을 설정하지 않으면 최소 Byte 수에 대한 유효성 체크를 수행하지 않습니다.",
        "입력값이 없거나 입력값의 Byte 수가 설정값보다 작으면 유효성 체크는 실패로 처리되고 displaymessage 속성에 따라 실패 메시지가 출력됩니다.",
        "시스템 기본 메시지는 'n byte 이상 입력해야 합니다.' 이며, invalidMessage 또는 invalidMessageFunc 속성으로 메시지를 변경할 수 있습니다.",
        "maxBytelength 또는 maxlength 속성을 minByteLength 값보다 작게 설정한 경우 유효성 체크는 항상 실패로 처리됩니다.",
        "minlength 를 함께 설정한 경우 minlength 의 유효성 체크가 먼저 실행됩니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // 정적 select1 기본값 설정 (gdl_boolean 은 코드값, 자체 값 selectbox 는 value)
    con_value.setValue("abcde");
    con_subProperty.setSelectedIndex(0);
    con_displaymessage.setValue("2");
    con_invalidMessageFunc.setValue("1");

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 컴포넌트 있으면 삭제
    if (typeof label1 !== 'undefined') {
        label1.remove();
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    $c.gcm.createLabel('label="입력값은 password 로 표시되어 화면에서 글자 수를 셀 수 없으므로, 결과창에 출력되는 값 길이와 Byte 수(euc-kr 기준 한글 1자 2Byte)로 판정합니다"', '', 'label1');

    // 조건 설정
    scwin.gVar["cMinByteLength"] = con_minByteLength.getValue();
    scwin.gVar["cValue"] = con_value.getValue();
    scwin.gVar["cSubProperty"] = con_subProperty.getValue();
    scwin.gVar["cDisplaymessage"] = con_displaymessage.getText();
    scwin.gVar["cInvalidMessage"] = con_invalidMessage.getValue();
    scwin.gVar["cInvalidMessageFunc"] = con_invalidMessageFunc.getText();

    let properties = {
        minByteLength : scwin.gVar["cMinByteLength"],
        displaymessage : scwin.gVar["cDisplaymessage"],
        invalidMessage : scwin.gVar["cInvalidMessage"],
        invalidMessageFunc : scwin.gVar["cInvalidMessageFunc"],
    }

    // minByteLength 와 함께 설정할 속성 (선택한 1개만 적용)
    if (scwin.gVar["cSubProperty"] === "minlength")
        properties.minlength = "10";
    else if (scwin.gVar["cSubProperty"] === "maxlength")
        properties.maxlength = "3";
    else if (scwin.gVar["cSubProperty"] === "maxByteLength")
        properties.maxByteLength = "3";

    let cList = $c.gcm.createCList(properties);

    // comp 생성 함수 호출
    await $c.gcm.createBasicSecret(cList);

    // 헬퍼가 넣은 초기값 secret 을 선택한 입력값으로 덮음 (빈값 선택 시 입력값 없음 케이스 재현)
    if (scwin.gVar["cValue"] === "empty")
        target1.setValue("");
    else
        target1.setValue(scwin.gVar["cValue"]);
}



// validate 실행 (minByteLength 발동 수단) - validation 1 ~ 8 판정 출력
scwin.btn_validate_onclick = function (e) {
    // password 는 화면으로 글자 수 확인이 불가하므로 판정 근거로 값 길이와 Byte 수를 함께 출력
    let strValue = target1.getValue() || "";
    let nLength = strValue.length;
    let nByte = WebSquare.util.getStringByteSize(strValue);
    let strEncoding = WebSquare.core.getConfiguration("/WebSquare/byteCheckEncoding/@value");

    let rtn = target1.validate();

    let strMinByteLength = (scwin.gVar["cMinByteLength"] === "") ? "미설정" : scwin.gVar["cMinByteLength"];
    let strSubProperty = (scwin.gVar["cSubProperty"] === "") ? "미설정" : scwin.gVar["cSubProperty"];
    let strDisplaymessage = (scwin.gVar["cDisplaymessage"] === "") ? "미설정" : scwin.gVar["cDisplaymessage"];
    let strInvalidMessage = (scwin.gVar["cInvalidMessage"] === "") ? "미설정" : scwin.gVar["cInvalidMessage"];
    let strInvalidMessageFunc = (scwin.gVar["cInvalidMessageFunc"] === "") ? "미설정" : scwin.gVar["cInvalidMessageFunc"];

    wf_body_bottom.getObj("scwin").setReturnValue("minByteLength " + strMinByteLength + " / 동시 설정 " + strSubProperty + " / displaymessage " + strDisplaymessage + " / invalidMessage " + strInvalidMessage + " / invalidMessageFunc " + strInvalidMessageFunc + " / 입력값 " + nLength + "자 " + nByte + "byte (byteCheckEncoding " + strEncoding + ") -> validate() 반환값 : " + rtn);
}



// invalidMessageFunc 로 설정되는 사용자 정의 메시지 함수
scwin.fn_msg = function () {
    return "invalidMessageFunc 메시지 (원인 : " + this.getType() + ")";
}
